import{_ as t,o as i,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"文件上传","description":"","frontmatter":{"title":"文件上传","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","常见需求","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第十部分：常见需求/文件上传/文件上传.md","filePath":"posts/java快速入门/第十部分：常见需求/文件上传/文件上传.md"}'),a={name:"posts/java快速入门/第十部分：常见需求/文件上传/文件上传.md"};function s(n,e,p,l,m,c){return i(),o("div",null,[...e[0]||(e[0]=[r("<div><p>package com.dhcc.common.utils;</p><p>// 导入所需的包 import com.aoip.common.core.util.UuidUtil; import com.dhcc.common.enums.FilePatternEnum; import com.dhcc.common.enums.LogicDelFlagEnum; import com.dhcc.common.exception.CustomerException; import com.dhcc.common.vo.FileVo; import lombok.RequiredArgsConstructor; import org.apache.commons.io.FileUtils; import org.apache.commons.io.FilenameUtils; import org.apache.commons.lang3.EnumUtils; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.context.properties.EnableConfigurationProperties; import org.springframework.stereotype.Component; import org.springframework.web.multipart.MultipartFile;</p><p>import javax.annotation.PostConstruct; import java.io.File; import java.io.IOException; import java.nio.file.Files; import java.nio.file.Path; import java.nio.file.Paths; import java.nio.file.attribute.PosixFilePermission; import java.time.LocalDateTime; import java.time.format.DateTimeFormatter; import java.util.HashSet; import java.util.Set;</p><p>/**</p><ul><li>@author zhilin</li><li>@since 2023/4/11 11:35 */ // 定义为Spring组件 @Component // 启用Spring的配置属性功能，该功能会根据properties文件或YAML文件中的配置自动填充Bean的字段 @EnableConfigurationProperties(FileProperties.class) // 注入需要的对象 @RequiredArgsConstructor(onConstructor = @__(@Autowired)) public class UploadUtil {</li></ul><p>private static final Logger log = LoggerFactory.getLogger(UploadUtil.class); private final FileProperties fileProperties;</p><p>private static FileProperties configFileProperties;</p><p>private static final String PATH_SEPARATOR = File.separator; private static final DateTimeFormatter YEAR_MONTH_FORMATTER = DateTimeFormatter.ofPattern(&quot;yyyy/MM&quot;);</p><p>// 在Spring构造该Bean后执行这个方法 @PostConstruct public void init() { // 将Spring管理的Bean的引用赋值给静态变量，以便在静态方法中使用 configFileProperties = this.fileProperties; }</p><p>// 上传文件的方法 public static FileVo upload(MultipartFile file, String moduleName, String childDir, Integer type) { // 获取当前操作系统 String os = System.getProperty(&quot;os.name&quot;).toLowerCase();</p><p>// 根据不同的操作系统，设置不同的目录 String baseDir = &quot;/home&quot;; if (os.contains(&quot;mac&quot;)) { baseDir = &quot;/Users&quot;; }</p><p>// 针对macOS, 我们需要更改配置文件中存储的路径为/Users/username/路径 String path; if (os.contains(&quot;mac&quot;)) { path = baseDir + &quot;/&quot; + System.getProperty(&quot;user.name&quot;) + configFileProperties.getPath(); } else { path = configFileProperties.getPath(); }</p><p>// 获取当前日期的年份和月份字符串 String yearMonth = LocalDateTime.now().format(YEAR_MONTH_FORMATTER);</p><p>// 使用路径分隔符连接模块名、子目录和年份月份字符串，生成目录名后缀 String suffix = String.join(PATH_SEPARATOR, moduleName.toLowerCase(), childDir.toLowerCase(), yearMonth);</p><p>// 使用Paths类的get方法拼接完整的目录路径 Path dirPath = Paths.get(path, suffix);</p><p>// 获取上传文件的名称，不包含扩展名 String fileName = FilenameUtils.getBaseName(file.getOriginalFilename());</p><p>// 获取上传文件的扩展名 String extension = FilenameUtils.getExtension(file.getOriginalFilename());</p><p>// 校验文件类型 if (extension == null || !EnumUtils.isValidEnumIgnoreCase(FilePatternEnum.class, extension)) { throw new CustomerException(500, &quot;文件格式错误!&quot;); }</p><p>// 创建目录 File dir = dirPath.toFile(); if (!dir.exists() &amp;&amp; !dir.mkdirs()) { throw new CustomerException(500, &quot;无法创建目录!&quot;); }</p><p>// 检查文件是否为空 if (!file.isEmpty()) { try { // 使用Paths类的get方法拼接完整的文件路径 Path filePath = Paths.get(dirPath.toString(), UuidUtil.get32Uuid() + &quot;.&quot; + extension); File newFile = filePath.toFile();</p><p>// 转移文件 file.transferTo(newFile);</p><p>// 设置文件权限 if (!(newFile.setReadable(true) &amp;&amp; newFile.setWritable(true))) { log.warn(&quot;Failed to set readable/writable permissions for {}&quot;, newFile.getName()); }</p><p>// 构建并返回文件信息对象 return new FileVo().builder() .fileName(fileName) .filePath(suffix + PATH_SEPARATOR + newFile.getName()) .fileType(extension.toUpperCase()) .fileSize(FileUtils.byteCountToDisplaySize(newFile.length())) .dataFlag(type) .delFlag(LogicDelFlagEnum.UNDELETE.getValue()) .build(); } catch (IOException e) { log.error(&quot;文件上传失败: &quot;, e); throw new CustomerException(500, &quot;文件上传失败!&quot;); } } else { throw new CustomerException(500, &quot;未接收到文件,请重新尝试&quot;); } }</p><p>// 通过NIO方式给文件赋权，以保证文件能够正常打开 private static void changeFolderPermission(File file) throws IOException { Set&lt;PosixFilePermission&gt; perms = new HashSet&lt;&gt;(); perms.add(PosixFilePermission.OWNER_READ); perms.add(PosixFilePermission.OWNER_WRITE); perms.add(PosixFilePermission.OWNER_EXECUTE); perms.add(PosixFilePermission.GROUP_READ); perms.add(PosixFilePermission.GROUP_WRITE); perms.add(PosixFilePermission.GROUP_EXECUTE); perms.add(PosixFilePermission.OTHERS_READ); perms.add(PosixFilePermission.OTHERS_WRITE); perms.add(PosixFilePermission.OTHERS_EXECUTE); try { Path path = Paths.get(file.getAbsolutePath()); Files.setPosixFilePermissions(path, perms); } catch (Exception e) { log.error(&quot;文件赋值权限异常：&quot;, e); } } }</p></div>",1)])])}const P=t(a,[["render",s]]);export{g as __pageData,P as default};
